vec3 Vignette(in vec3 rgb, in vec2 fragCoord)
{
    #define kVignetteStrength         1.             // The strength of the vignette effect
    #define kVignetteScale            0.6            // The scale of the vignette effect
    #define kVignetteExponent         2.5            // The rate of attenuation of the vignette effect

    vec2 uv = fragCoord / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y) + 0.5;     

    float x = 2.0 * (uv.x - 0.5);
    float y = 2.0 * (uv.y - 0.5);

    float dist = sqrt(x*x + y*y) / kRoot2;

    float v = mix(1.0, max(0.0, 1.0 - pow(dist * kVignetteScale, kVignetteExponent)), kVignetteStrength);
    return rgb * v;
    //return pow(rgb, vec3(1. + (1. - v)));

}

float Smoothstep(float a, float b, float t) { return mix(a, b, t * t * (3. - 2. * t)); }

vec3 ChromaticAberration(sampler2D sampler, in vec2 xyScreen, int chnl, float magnitude)
{
    #define kAbbSafeZone 0.
    #define kAbbMagnitude 0.02

    vec3 rgb = kZero;
    vec2 ratio = vec2(max(1., iResolution.x / iResolution.y), max(1., iResolution.y / iResolution.x));
    vec2 uv = ratio * (xyScreen / iResolution.xy - vec2(0.5));
    float d = length(uv);

    for(int c = 0; c < 3; ++c)
    {
        vec2 uvc = uv / (1. + Smoothstep(0., kAbbMagnitude, saturate(d - kAbbSafeZone) * mix(0.5, 0., (float(c) + OrderedDither(ivec2(xyScreen))) / 3.)));
        vec4 texel = texture(sampler, (uvc / ratio) + vec2(0.5), 0.);
        rgb[c] = texel[c] / texel.w;

    }
    return rgb;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{        
    vec3 L = ChromaticAberration(iChannel0, xyScreen, 1, 0.007);

    vec2 uv = 4. * xyScreen / iResolution.xy;
    if(uv.y < 1. && uv.x < 1.)
    {
        EvaluatePDF2(iChannel1, vec2(uv.x, 1. - uv.y), L);
    }

    vec3 bloom = SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.05), vec3(1.5, 1.8, 2.4), 0, iChannel2) * 1.; 
    bloom += SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.1), vec3(1.0, 1.8, 2.4), 1, iChannel2) * 1.;
    L += pow(bloom * 2., vec3(1., 1.1, 1.2)) * 0.25; 

    L = pow(L * 1.3, vec3(.9));

    L = Vignette(L, xyScreen);   

    int i = int(xyScreen.x), j = int(xyScreen.y), w = int(iResolution.x), h = int(iResolution.y);
    if((abs(i - w / 4) <= 1 && j <= h / 4) || (abs(j - h / 4) <= 1 && i <= w / 4))
    {
        L = kZero;
    }

    rgba = vec4(L, 1.);

    if(abs(int(xyScreen.x) - int(iResolution.x * 0.5)) <= 1) { rgba.xyz =kZero; }
}

// RENDER PASS

#define kInvalidMaterial -1
#define kMatEmitter 0
#define kMatRoughSpecular 1
#define kMatRoughDielectric 2
#define kMatPerfectSpecular 3
#define kMatPerfectDielectric 4
#define kMatLambertian 5
#define kMatCompound 6

#define kEmitterPos vec3(0., 0.5, 0.5)
#define kEmitterRot vec3(0.5 * kPi * 1.5, 0., 0.)
//#define kEmitterSca mix(0.1, 1.5, sin01(iTime * 0.5))
#define kEmitterSca 0.1
#define kEmitterPower 1.
#define kEmitterRadiance (kOne * kEmitterPower / sqr(kEmitterSca))

// Ray-plane intersection test
bool RayPlane(inout Ray ray, bool bounded, inout HitCtx hit, in Transform transform)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);
    if(localRay.o.z <= 0. || abs(localRay.d.z) < 1e-10) { return false; } 

    float t = localRay.o.z / -localRay.d.z;
    if (t <= 0.0 || t >= ray.tNear) { return false; }

    float u = (localRay.o.x + localRay.d.x * t) + 0.5;
    float v = (localRay.o.y + localRay.d.y * t) + 0.5;

    if(bounded && (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0)) { return false; }   

    ray.tNear = t;
    SetRayFlag(ray, kFlagsBackfacing, localRay.o.z < 0.0);
    hit.n = transpose(transform.rot) * vec3(0.0, 0.0, 1.0);
    hit.tangent = transpose(transform.rot) * vec3(1.0, 0.0, 0.0);
    hit.cotangent = transpose(transform.rot) * vec3(0.0, 1.0, 0.0);
    hit.uv = vec2(u, v);

    return true;
}

// Ray-sphere intersection test
bool RaySphere(inout Ray ray, inout HitCtx hit, in Transform transform)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);

    // A ray intersects a sphere in at most two places which means we can find t by solving a quadratic
    float a = dot(localRay.d, localRay.d);
    float b = 2.0 * dot(localRay.d, localRay.o);
    float c = dot(localRay.o, localRay.o) - 1.0;

    float t0, t1;
    if(!QuadraticSolve(a, b, c, t0, t1)) { return false; }

    sort(t0, t1);   

    vec3 n;
    float tNear = ray.tNear;
    if(t0 > 0.0 && t0 < tNear) { tNear = t0; }
    else if(t1 > 0.0 && t1 < tNear) { tNear = t1; }
    else { return false; }

    //if(dot(localRay.o, localRay.o) < 1.0) return false; // Ignore backfacing

    ray.tNear = tNear;
    hit.n = transpose(transform.rot) * (localRay.o + localRay.d * tNear);
    hit.kickoff = 1e-4;
    if(dot(localRay.o, localRay.o) < 1.0)
    {
        SetRayFlag(ray, kFlagsBackfacing, true);
        hit.n = -hit.n;
    }

    return true;
}

Ray CreatePinholeCameraRay(vec2 uvScreen, vec3 cameraPos, vec3 cameraLookAt, float fov)
{   
    Ray ray;
    ray.od.o = cameraPos;
    ray.od.d = transpose(CreateBasis(normalize(cameraPos - cameraLookAt), vec3(0., 1., 0.))) * normalize(vec3(uvScreen, -1. / tan(toRad(fov))));
    ray.tNear = kFltMax;
    ray.weight = vec3(1.0, 1.0, 1.0);
    ray.flags = kFlagsCausticPath;
    ray.depth = 0;

    return ray;  
}

Ray CreatePerspectiveCameraRay(vec2 uvScreen, vec3 cameraPos, vec3 cameraLookAt, float focalLength, float fStop, vec4 xi, vec2 resolution)
{        
    // Define our camera vectors and orthonormal basis
    #define kCameraUp vec3(0.0, 1.0, 0.0)    

    vec3 kCameraForward = cameraLookAt - cameraPos;
    float focalDistance = length(kCameraForward);
    kCameraForward /= focalDistance;

    mat4 basis;
    basis[0] = vec4(normalize(cross(kCameraForward, kCameraUp)), 0.0);
    basis[1] = vec4(cross(basis[0].xyz, kCameraForward), 0.0);
    basis[2] = vec4(kCameraForward, 0.0);
    basis[3] = vec4(0.0, 0.0, 0.0, 1.0);
    basis = transpose(basis);

    // Define the focal length and F-number depending, either from built-in or user-defined values
    #define kCameraSensorSize         0.035 
    #define kCameraAA 1.0

    // Solve the thin-lens equation. http://hyperphysics.phy-astr.gsu.edu/hbase/geoopt/lenseq.html
    float d1 = 0.5 * (focalDistance - sqrt(-4.0 * focalLength * focalDistance + sqr(focalDistance)));
    float d2 = focalDistance - d1; 

    // Generate a position on the sensor, the focal plane, and the lens. This lens will always have circular bokeh
    // but with a few minor additions it's possible to add custom shapes such as irises. We reuse some random numbers
    // but this doesn't really matter because the anti-aliasing kernel is so small that we won't notice the correlation 
    vec2 boxMuller = 0.5 * sqrt(-2. * log(xi.x)) * vec2(cos(kTwoPi * xi.y), sin(kTwoPi * xi.y));    
    vec2 sensorPos = boxMuller * kCameraSensorSize * kCameraAA / max(resolution.x, resolution.y) + uvScreen * kCameraSensorSize;    
    vec2 focalPlanePos = vec2(sensorPos.x, sensorPos.y) * d2 / d1;    
    vec2 lensPos = SampleUnitDisc(xi.xy) * 0.5 * focalLength / fStop;

    // Assemble the ray
    Ray ray;
    ray.od.o = mul3(vec3(lensPos, d1), basis);
    ray.od.d = normalize(mul3(vec3(focalPlanePos, focalDistance), basis) - ray.od.o);
    ray.od.o += cameraPos;
    ray.tNear = kFltMax;
    ray.weight = vec3(1.0, 1.0, 1.0);
    ray.flags = kFlagsCausticPath;
    ray.depth = 0;

    return ray;    
}

///////////////// QUAD LIGHT //////////////////////

float SampleQuadLight(in Ray incident, out Ray extant, inout HitCtx hit, inout Transform emitterTrans, in vec2 xi)
{
    // Sample a point on the light 
    vec3 hitPos = PointAt(incident);

    //vec2 xi = vec2(0.0);
    //uint hash = HashOf(uint(gFragCoord.x), uint(gFragCoord.y));
    //vec2 xi = vec2(HaltonBase2(hash + uint(sampleIdx)), HaltonBase3(hash + uint(sampleIdx))) - 0.5;

    vec3 lightPos = transpose(emitterTrans.rot) * vec3(xi-0.5, 0.) * emitterTrans.sca + emitterTrans.trans;    
    //lightPos = emitterTrans.trans;

    // Compute the normalised extant direction based on the light position local to the shading point
    vec3 outgoing = lightPos - hitPos;
    float lightDist = length(outgoing);
    outgoing /= lightDist;

    // Test if the emitter is behind the shading point
    if (dot(outgoing, hit.n) <= 0.) { return 0.0; }

    vec3 lightNormal = normalize(transpose(emitterTrans.rot) * vec3(0.0, 0.0, 1.0));
    float cosPhi = dot(normalize(hitPos - lightPos), lightNormal);

    // Test if the emitter is rotated away from the shading point
    if (cosPhi < 0.) { return 0.0; }

    // Compute the projected solid angle of the light        
    float solidAngle = cosPhi * sqr(emitterTrans.sca) / max(1e-10, sqr(lightDist));   

    // Create the ray from the sampled BRDF direction
    CreateRay(extant, hitPos,
                    outgoing, 
                    (IsBackfacing(incident) ? -hit.n : hit.n) * hit.kickoff,
                    //hit.n * 1e-4,
                    incident.weight * kEmitterRadiance * solidAngle,
                    incident.depth + 1,
                    kFlagsDirectSampleLight);      

    return 1.0 / max(1e-10, solidAngle);
}

float EvaluateQuadLight(inout Ray ray, inout HitCtx hit, inout Transform emitterTrans) 
{    
    RayBasic localRay = RayToObjectSpace(ray.od, emitterTrans);
    if(abs(localRay.d.z) < 1e-10) { return 0.0; } 

    float t = localRay.o.z / -localRay.d.z;

    vec2 uv = (localRay.o.xy + localRay.d.xy * t) + 0.5;
    if(cwiseMin(uv) < 0.0 || cwiseMax(uv) > 1.0) { return 0.0; }    

    vec3 lightNormal = normalize(transpose(emitterTrans.rot) * vec3(0.0, 0.0, 1.0));
    vec3 lightPos = ray.od.o + ray.od.d * t;

    float cosPhi = dot(normalize(ray.od.o - lightPos), lightNormal);

    // Test if the emitter is rotated away from the shading point
    if (cosPhi < 0.) { return 0.0; }

    float solidAngle = cosPhi * sqr(emitterTrans.sca) / max(1e-10, sqr(t));

    //if(!IsVolumetricBxDF(hit))
    {    
        float cosTheta = dot(hit.n, ray.od.d);
        if (cosTheta < 0.0f)  { return 0.0; }

        solidAngle *= cosTheta;   
    }

    ray.weight *= kEmitterRadiance;
    ray.flags = kFlagsDirectSampleBxDF;
    return 1.0 / max(1e-10, solidAngle);
}

///////////////// ENVIRONMENT LIGHT //////////////////////

float SampleEnvLight(in Ray incident, out Ray extant, inout HitCtx hit, in vec2 xi, inout vec3 L)
{       
    // Draw an environment sample
    vec2 q;
    vec3 envRadiance;
    float pdf = SamplePDF2(iChannel1, xi, q, envRadiance) / kFourPi;

    // Determine the outgoing ray direction
    float phi = kTwoPi * q.x, theta = kPi * q.y;
    vec3 outgoing = vec3(cos(phi) * sin(theta), sin(phi) * sin(theta), cos(theta));    

    //if(!IsVolumetricBxDF(hit))
    {
        // Discard rays that aren't in the unit hemisphere
        if(dot(outgoing, hit.n) < 0.) { return 0.; }   
    }

    // Create the ray from the sampled BRDF direction
    CreateRay(extant, PointAt(incident),
              outgoing, 
              (IsBackfacing(incident) ? -hit.n : hit.n) * hit.kickoff,
              incident.weight * envRadiance / max(1e-10, pdf),
              incident.depth + 1,
              kFlagsDirectSampleLight | kFlagsDirectSampleEnv);      

    return pdf;
}

float EvaluateEnvLight(inout Ray ray, inout HitCtx hit) 
{
    float phi = atan2(ray.od.d.y, ray.od.d.x) / kTwoPi;
    float theta = acos(ray.od.d.z) / kPi;

    // Evaluate the environment
    vec3 envRadiance;
    float pdf = EvaluatePDF2(iChannel1, vec2(phi, theta), envRadiance) / kFourPi;

    ray.weight *= envRadiance;
    ray.flags = kFlagsDirectSampleBxDF | kFlagsDirectSampleEnv;
    return pdf;   
}

////////////////////////////////////////////////////////

float PowerHeuristic(float pdf1, float pdf2)
{
    return saturate(sqr(pdf1) / max(1e-10, sqr(pdf1) + sqr(pdf2)));
}

float SampleEmitter(in Ray incident, out Ray extant, in HitCtx hit, in Transform emitterTrans, in vec2 xi, inout vec3 L)
{
    vec3 i = -incident.od.d;
    //float emitterPdf = SampleQuadLight(incident, extant, hit, emitterTrans, xi);        
    float emitterPdf = SampleEnvLight(incident, extant, hit, xi, L);
    if(emitterPdf <= 0.) { return 0.; }            

    float bxdfPdf;
    switch(hit.matID) 
    {
        case kMatLambertian:
        {
            bxdfPdf = EvaluateLambertian(); 
            break;
        }
        case kMatRoughSpecular:
        {
            bxdfPdf = EvaluateMicrofacetReflectorGGX(i, extant.od.d, hit.n, hit.alpha);
            break;
        }
        default:
            L += kRed * 1e3; return 0.; // Should never be here!
    }

    // Lambert cosine factor
    bxdfPdf *= dot(extant.od.d, hit.n);    

    extant.weight *= 2. * bxdfPdf * PowerHeuristic(emitterPdf, bxdfPdf);

    return emitterPdf;
}

float SampleBxDF(in Ray incident, out Ray extant, in HitCtx hit, in Transform emitterTrans, in vec2 xi, in bool useMis, inout vec3 L)
{
    vec3 o;
    float bxdfPdf, brdfWeight = 1.;
    switch(hit.matID) 
    {    
        case kMatLambertian:
        {
            bxdfPdf = SampleLambertian(xi, hit.n, o); 
            break;
        }
        case kMatPerfectSpecular:
        {
            bxdfPdf = SamplePerfectSpecular(-incident.od.d, hit.n, o);
            break;
        }
        case kMatPerfectDielectric:
        {
            bxdfPdf = SamplePerfectDielectric(xi.y, -incident.od.d, hit.n, hit.alpha, o, IsBackfacing(incident), hit.kickoff);
            if(IsBackfacing(incident))
            {
                //vec3 hue = mix(kOne, kOne - Hue(0.6), 0.8);
                //incident.weight *= exp(-incident.tNear * kOne * 100.);
            }
            break;
        }
        case kMatRoughSpecular:
        {
            bxdfPdf = SampleMicrofacetReflectorGGX(xi, -incident.od.d, hit.n, hit.alpha, o, brdfWeight);
            break;
        }
    }    

    if(bxdfPdf <= 0.) { return 0.; }

    CreateRay(extant, PointAt(incident), o, hit.n * hit.kickoff, incident.weight * brdfWeight, incident.depth + 1, InheritFlags(incident)); 

    if(!(hit.matID == kMatPerfectSpecular || hit.matID == kMatPerfectDielectric)) { extant.flags |= kFlagsScattered; }

    if(useMis)
    {
        //float emitterPdf = EvaluateQuadLight(extant, hit, emitterTrans); 
        float emitterPdf = EvaluateEnvLight(extant, hit); 
        extant.weight *= 2. * PowerHeuristic(bxdfPdf, emitterPdf);
        extant.flags |= kFlagsDirectSampleBxDF | kFlagsDirectSampleEnv;
    }

    return bxdfPdf;
}

#define kGenerateNothing 0
#define kGeneratedDirect 1
#define kGeneratedIndirect 2

#define kModePathTraced 0
#define kModeNEE 1

int Shade(in Ray incident, inout Ray indirectRay, inout Ray directRay, in HitCtx hit, inout RenderCtx renderCtx, Transform emitterTrans, int renderMode, inout vec3 L)
{             
    // Generate some random numbers
    float5 xi;
    xi = QRand5(renderCtx.rng, uint((1 + incident.depth) * 5));
    float xiSplit = fract(OrderedDither(renderCtx.xyScreen) + float(iFrame) / 16.);

    if(hit.matID == kMatCompound)
    {
        hit.matID = (xiSplit < 0.1) ? kMatPerfectSpecular : kMatLambertian;
    }

    incident.weight *= hit.albedo;

    if(hit.matID == kMatPerfectSpecular || hit.matID == kMatPerfectDielectric)  { renderMode = kModePathTraced; }

    int genFlags = 0;
    if(renderMode == kModeNEE)
    {
        if(xiSplit < 0.5)
        {   
            if(SampleEmitter(incident, directRay, hit, emitterTrans, vec2(xi[0], xi[1]), L) > 0.)
            {
                genFlags |= kGeneratedDirect; 
            }
        }
        else
        {        
            if(SampleBxDF(incident, directRay, hit, emitterTrans, vec2(xi[0], xi[1]), true, L) > 0.)
            {
                genFlags |= kGeneratedDirect;
            }            
        }
    }

    if(/*renderMode == kModePathTraced && */SampleBxDF(incident, indirectRay, hit, emitterTrans, vec2(xi[2], xi[3]), false, L) > 0.)
    {
        genFlags |= kGeneratedIndirect;
    } 

    return genFlags;
}

float CosMix(float a, float b, float t)
{
    t = saturate(t);
    return mix(a, b, t*t*(3. - 2.*t));
    //return mix(a, b, cos(kPi + kPi * saturate(t)) * 0.5 + 0.5);
}

float FBM2D(vec2 uv, float scale)
{
    uv = (uv + vec2(1e3)) * scale;
    float accum = 0.;
    #define kFBMNumHarm 5
    for(int harmIdx = 0; harmIdx < kFBMNumHarm; ++harmIdx)
    {
        vec2 uvHarm = uv * pow(2., float(harmIdx));
        vec4 p;
        p.x = UintToFloat01(HashOf(uint(harmIdx), uint(uvHarm.x), uint(uvHarm.y)), 16);
        p.y = UintToFloat01(HashOf(uint(harmIdx), uint(uvHarm.x) + 1u, uint(uvHarm.y)), 16);
        p.z = UintToFloat01(HashOf(uint(harmIdx), uint(uvHarm.x), uint(uvHarm.y) + 1u), 16);
        p.w = UintToFloat01(HashOf(uint(harmIdx), uint(uvHarm.x) + 1u, uint(uvHarm.y) + 1u), 16);

        accum += CosMix(CosMix(p.x, p.y, fract(uvHarm.x)), CosMix(p.z, p.w, fract(uvHarm.x)), fract(uvHarm.y)) / pow(2., float(1 + harmIdx));
    }
    return saturate(accum);
}

float Grid2D(vec2 uv, float thickness)
{
    return step(thickness, fract(uv.x)) * step(thickness, fract(uv.y));
}

vec3 PerturbNormal(inout HitCtx hit, sampler2D sampler, float alpha, float delta)
{
    alpha = sign(alpha) * sqr(alpha);

    float dpdu = luminance(texture(sampler, hit.uv + vec2(-delta, 0.), 0.).xyz - texture(sampler, hit.uv + vec2(delta, 0.), 0.).xyz) / (2. * delta);
    float dpdv = luminance(texture(sampler, hit.uv + vec2(0., -delta), 0.).xyz - texture(sampler, hit.uv + vec2(0., delta), 0.).xyz) / (2. * delta);

    return normalize(hit.n + (hit.tangent * dpdu + hit.cotangent * dpdv) * alpha);    
}

int Trace(inout Ray ray, out HitCtx hit, bool indirectLambert, in float xi, out float FMin)
{
    Transform transform;
    hit.matID = kInvalidMaterial;  
    hit.objID = kInvalidMaterial;

    // Spheres with different matertials
    #define kNumSpheres 7
    for(int sphereIdx = 0; sphereIdx < kNumSpheres; ++sphereIdx)
    {
        float phi = kTwoPi * (float(sphereIdx) / float(kNumSpheres));
        transform = CompoundTransform(vec3(cos(phi), 0., sin(phi)) * 0.7, vec3(0., 0., 0.), 0.2);

        if(RaySphere(ray, hit, transform))
        {
            switch(sphereIdx)
            {
            case 0:
                hit.matID = kMatPerfectSpecular; break;
            case 1:
                hit.matID = kMatPerfectDielectric; 
                hit.alpha = 1.5;
                break;
            case 2:
                hit.matID = kMatLambertian;
                break;
            case 3:
                hit.matID = kMatCompound;
                hit.alpha = 0.2;
                break;
            default:
                hit.matID = kMatRoughSpecular;
                hit.alpha = mix(0.01, 0.5, sqr(float(sphereIdx - 4) / float(kNumSpheres - 4)));
                break;
            }   
            hit.albedo = 1.;
        }
    }

    // Ground plane
    transform = CompoundTransform(vec3(0., -0.2, 0.), vec3(-0.5 * kPi, 0., 0.), 2.);
    if(RayPlane(ray, false, hit, transform))
    {
        hit.objID = 2;
        hit.matID = kMatLambertian;

        hit.albedo = mix(0.1, 0.4, Grid2D(hit.uv * 10., 0.1));      
    }

    // Make all materials diffuse Lambert
    //if(hit.matID != kInvalidMaterial && hit.matID != kMatEmitter)  hit.matID = kMatLambertian;  

    return hit.matID;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    // Mouse state
    if(int(xyScreen.x) == 0 && int(xyScreen.y) == 0)
    {
        if(iFrame == 0) { rgba *= 0.; return; }
        rgba = texelFetch(iChannel0, ivec2(0), 0);
        if(iMouse.z > 0.) { rgba.x = 1.; }
        return;
    }

    // Idle for as many frames as it takes to build the environment sampler
    rgba *= 0.;
    if(iFrame <= 4 + kPDF2PhiSteps + kPDF2ThetaSteps) { return; }

    bool kAutoRotate = bool(texelFetch(iChannel0, ivec2(0), 0).x == 0.);

    rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);
    if(iMouse.z > 0.0) rgba *= 0.;
    //rgba *= 0.;

    RenderCtx renderCtx;
    renderCtx.xyScreen = ivec2(xyScreen);
    float5 xi;
    renderCtx.rng.x = 98796235u;
    renderCtx.rng.y = HashOf(uint(xyScreen.x), uint(xyScreen.y)) + uint(iFrame);
    xi = Rand5(renderCtx.rng);
    xi[4] = HaltonBase2(renderCtx.rng.y);    

    HitCtx hitCtx;
    Transform emitterTrans;// = CompoundTransform(kEmitterPos, kEmitterRot, kEmitterSca);

    vec2 uvView = ScreenToNormalisedScreen(xyScreen + vec2(xi[0], xi[1]), iResolution.xy);   

    float cameraPhi = -kPi;
    cameraPhi += kTwoPi * mix(-1., 1., iMouse.x / iResolution.x);
    if(kAutoRotate) cameraPhi += kTwoPi * iTime * 0.005;
    vec3 cameraPos = vec3(cos(cameraPhi), 0.5, sin(cameraPhi));//mix(0.5, 3., iMouse.y / iResolution.y);
    cameraPos *= kAutoRotate ? mix(2.3, 1.8, sin01(iTime * 0.05)) : 1.8;

    //Ray indirectRay = CreatePinholeCameraRay(uvView, cameraPos, vec3(0., -0.1, -0.), 40.);
    Ray indirectRay = CreatePerspectiveCameraRay(uvView, cameraPos, vec3(0., -0.15, -0.), 0.045, 1.7, vec4(xi[0], xi[1], xi[2], xi[3]), iResolution.xy);  

    Ray directRay;
    Ray ray;
    int genFlags = kGeneratedIndirect;
    HitCtx hit;
    vec3 L = kZero;

    // Left half of screen = path traced reference. Right half = path tracing + NEE
    int renderMode = (xyScreen.x < iResolution.x * 0.5) ? kModePathTraced : kModeNEE;        

    #define kMaxPathDepth 5
    #define kMaxIterations 10
    for(int rayIdx = 0; rayIdx < kMaxIterations && genFlags != kGenerateNothing; ++rayIdx)
    {                
        if((genFlags & kGeneratedDirect) != 0) ray = directRay; else ray = indirectRay;        

        // ***** WEIGHT CLAMP ******
        //ray.weight = clamp(ray.weight, kZero, kOne * 10.);

        if(ray.depth >= kMaxPathDepth) { continue; }

        float rayFMin = 0.;
        if(Trace(ray, hit, false, xi[4], rayFMin) == kInvalidMaterial)
        {
            if(IsDirectSampleEnv(ray))
            {
                L += ray.weight; 
            }
            else if(renderMode == kModePathTraced || !IsScattered(ray)) // Environment light is importance sampled, so only evaluate it pure path tracing mode
            {
                float phi = atan2(ray.od.d.y, ray.od.d.x) / kTwoPi;
                float theta = acos(ray.od.d.z) / kPi;

                vec3 envRadiance;
                if(EvaluatePDF2(iChannel1, vec2(phi, theta), envRadiance) > 0.)
                {
                    L += ray.weight * envRadiance;
                }
                //L += kOne * EvaluateCubemap(iChannel3, ray.od.d);
                //L += kOne * 0.5;
            }

            break;
        }         

        if(IsDirectSampleEnv(ray)) { genFlags &= ~kGeneratedDirect; continue; }

        //L = hit.n * 0.5 + 0.5; break;

        if((genFlags & kGeneratedDirect) != 0)
        {
            if(hit.matID == kMatEmitter && !IsBackfacing(ray))
            {
                // If this sample is a light ray, all we need to know is whether or not it hit the light. 
                // If it did, just accumulate the weight which contains the radiant energy from the light sample.       
               L += ray.weight;
            }
            genFlags &= ~kGeneratedDirect; 
        }
        else if((genFlags & kGeneratedIndirect) != 0)
        {              
            if(hit.matID == kMatEmitter)
            {
                // Emitters don't reflect light, so simply accumulate its radiance and we're done
                if(!IsBackfacing(ray) && (!IsScattered(ray) || renderMode == kModePathTraced))
                {
                    L += kEmitterRadiance * ray.weight;
                }
                genFlags = 0;
            }
            else
            {            
                // Otherwise, shade indirect rays
                genFlags = Shade(ray, indirectRay, directRay, hit, renderCtx, emitterTrans, renderMode, L);
            }
        }
    }            

    // Clamp the values a bit to reduce bloom shimmer
    #define kSplatClamp 20.
    float LMax = cwiseMax(L);
    if(LMax > kSplatClamp) { L *= kSplatClamp / LMax; }

    if(kAutoRotate) { rgba *= 0.97; }
    rgba += vec4(L * 2., 1.);

    // NaN clipping (not sure why this is a problem)
    for(int c = 0; c < 4; ++c) if(isnan(rgba[c])) rgba = vec4(L, 1.);

    // Picture-in-picture PMF view
    vec2 uv = 4. * xyScreen / iResolution.xy;
    if(uv.y < 1. && uv.x < 1.)
    {
        rgba.xyz = kZero;
        EvaluatePDF2(iChannel1, vec2(uv.x, 1. - uv.y), rgba.xyz); 
        rgba.w = 1.;
    }
}

