float D_Beckmann(vec3 m, vec3 n, float alpha)
{
    alpha *= alpha;
    float cosThetaM = clamp(dot(m, n), -1., 1.);
    float tan2ThetaM = 1. / sqr(cosThetaM) - 1.;
    return step(0.0f, dot(m, n)) / (kPi * alpha * pow4(cosThetaM)) * exp(-tan2ThetaM / alpha);
}

float G1_BeckmannExact(vec3 v, vec3 m, vec3 n, float alpha)
{
    float cosThetaV = max(1e-15, dot(v, n));
    float tan2ThetaV = 1. / sqr(cosThetaV) - 1.;
    float a = 1. / (alpha * tan2ThetaV);
    return step(0.0f, dot(v, m) / cosThetaV) * 2. /
           (1.0f + ErfApprox(a) + 1. / (a * kRootPi) * exp(-a*a));
}

float G1_Beckmann (vec3 v, vec3 m, vec3 n, float alpha)
{
    float cosThetaV = max(1e-15, dot(v, n));
    float tan2ThetaV = 1. / sqr(cosThetaV) - 1.;
    float a = 1. / (alpha * tan2ThetaV);
    float b = step(0.0f, dot(v, m) / cosThetaV);
    if(a > 1.6) { return b; }

    return b * a * (3.535 + a * 2.181) / (1. + a * (2.267 + a * 2.577));
}

float G_Beckmann(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
     return G1_Beckmann(i, m, n, alpha) * G1_Beckmann(o, m, n, alpha);
}

float Weight_Beckmann(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
    #define kBeckmannWeightClamp 50.
    return min(kBeckmannWeightClamp, abs(dot(i, m)) * G_Beckmann(i, o, m, n, alpha) / (abs(dot(i, n) * dot(m, n))));
}

float EvaluateMicrofacetReflectorBeckmann(in vec3 i, in vec3 o, in vec3 n, float alpha)
{
    #define kBeckmannPDFClamp 50.

    vec3 hr = normalize(sign(dot(i, n)) * (i + o));

    float pdf = G_Beckmann(i, o, hr, n, alpha) * D_Beckmann(hr, n, alpha) / (4. * abs(dot(i, n) * dot(o, n)));
    return min(kBeckmannPDFClamp, pdf);
}

float SampleMicrofacetReflectorBeckmann(vec2 xi, vec3 i, vec3 n, float alpha, out vec3 o, out float weight)
{        
    // Sample the microsurface normal with the Beckmann distribution
    float thetaM = atan(-alpha*alpha * log(1. - xi.x));
    float sinThetaM = sin(thetaM);
    float phiM = kTwoPi * xi.y;
    vec3 m = CreateBasis(n) * vec3(cos(phiM) * sinThetaM, sin(phiM) * sinThetaM, cos(thetaM));
    o = reflect(-i, m);       

    weight = Weight_Beckmann(i, o, m, n, alpha);

    return (dot(o, n) <= 0.) ? 0. : EvaluateMicrofacetReflectorBeckmann(i, o, m, alpha);    
}

vec3 Hue(float phi)
{
    float phiColour = 6.0 * phi;
    int i = int(phiColour);
    vec3 c0 = vec3(((i + 4) / 3) & 1, ((i + 2) / 3) & 1, ((i + 0) / 3) & 1);
    vec3 c1 = vec3(((i + 5) / 3) & 1, ((i + 3) / 3) & 1, ((i + 1) / 3) & 1);             
    return mix(c0, c1, phiColour - float(i));
}

vec3 EvaluateCubemap(samplerCube sampler, vec3 n)
{
    // Constant
    //return kOne * 0.5;

    // Cubemap
    //return 2. * pow(texture(sampler, n.xzy * vec3(1, 1, 1)).xyz, vec3(1.5));

    uvec4 rng;
    rng = PCGInitialise(HashOf(uint(0)));    
    //vec3 L = kOne * 0.05; 
    vec3 L = kZero;
    #define kEnvConstellationAngle toRad(5.)
    #define kEnvConstellationGain 50.
    float cosAngle = cos(0.5 * kEnvConstellationAngle);
    vec3 norm = kZero;

    for(int i = 0; i < 20; ++i)
    {
        vec4 xi = Rand4(rng);
        vec3 d = SampleUnitSphere(xi.xy);        
        //vec3 colour = mix(kOne, Hue(acos(d.x) / kPi), 0.5);
        vec3 colour = kOne;
        norm += colour;

        float intensity = (saturate((dot(n, d) - cosAngle) / (1. - cosAngle)));
        L = max(L, colour * mix(0., kEnvConstellationGain, intensity));
    }    
    //L /= vec3(0.75, 1., 1.);    
    L = max(L, kOne * 0.3 * luminance(pow(texture(sampler, n.xzy * vec3(1, 1, 1)).xyz, vec3(1.5))));
    return L;    
}

vec3 EvaluateCubemap(samplerCube sampler, float theta, float phi)
{
    // Environment map
    vec3 n = vec3(cos(phi) * sin(theta), sin(phi) * sin(theta), cos(theta));    
    return EvaluateCubemap(sampler, n);
}

// Increase these values to increase the resolution of the environment sampler
#define kPDF2PhiSteps 9
#define kPDF2ThetaSteps 8
#define kPDF2Width (1 << kPDF2PhiSteps)
#define kPDF2Height (1 << kPDF2ThetaSteps)
#define kPDF2Dims ivec2(kPDF2Width, kPDF2Height)

float PiecewiseLinearSample(float y0, float y1, float xi)
{
    if(abs(y1 - y0) < 1e-10) { return xi; }    
    xi *= 0.5 * (y0 + y1);
    float m = y1 - y0;
    return ((-y0 + sqrt(max(0., y0*y0 + 2.*m*xi))) / m);
}

float SamplePDF2(sampler2D sampler, vec2 xi, out vec2 q, out vec3 L)
{    
    // Lower bound theta    
    int ay = 0, by = kPDF2Height - 1;
    while(by - ay > 1)
    {
        int h = ay + (by - ay) / 2;
        float fh = texelFetch(sampler, ivec2(kPDF2Width, h), 0).y;
        if(xi.y <= fh) { by = h; }
        else { ay = h; }
    }

    vec3 fay = texelFetch(sampler, ivec2(kPDF2Width, ay), 0).xyz;
    vec3 fby = texelFetch(sampler, ivec2(kPDF2Width, by), 0).xyz;  

    float dy = PiecewiseLinearSample(fay.z, fby.z, (xi.y - fay.y) / max(1e-10, fby.y - fay.y));
    //float dy = (xi.y - fay.y) / (fby.y - fay.y);   // Piecewise constant

    // Lower bound
    int ax = 0, bx = kPDF2Width - 1;   
    while(bx - ax > 1)
    {
        int h = ax + (bx - ax) / 2;
        float fh = mix(texelFetch(sampler, ivec2(h, ay), 0).y, texelFetch(sampler, ivec2(h, by), 0).y, dy);
        //float fh = texelFetch(sampler, ivec2(h, ay), 0).y;
        if(xi.x <= fh) { bx = h; }
        else { ax = h; }
    }

    vec4 t00 = texelFetch(sampler, ivec2(ax, ay), 0);
    vec4 t10 = texelFetch(sampler, ivec2(bx, ay), 0);
    vec4 t01 = texelFetch(sampler, ivec2(ax, by), 0);
    vec4 t11 = texelFetch(sampler, ivec2(bx, by), 0);

    vec4 fax = mix(t00, t01, dy);
    vec4 fbx = mix(t10, t11, dy);   

    float dx = PiecewiseLinearSample(fax.x, fbx.x, (xi.x - fax.y) / max(1e-10, fbx.y - fax.y));
    //float dx = (xi.x - fax.y) / (fbx.y - fax.y);  // Piecewise constant

    q = vec2((float(ax) + dx) / float(kPDF2Width - 1), 
             (float(ay) + dy) / float(kPDF2Height - 1));

    // Interpolate the radiance
    L = mix(mix(vec3(_unpackHalf2x16(floatBitsToUint(t00[2])), t00[3]), vec3(_unpackHalf2x16(floatBitsToUint(t10[2])), t10[3]), dx), 
            mix(vec3(_unpackHalf2x16(floatBitsToUint(t01[2])), t01[3]), vec3(_unpackHalf2x16(floatBitsToUint(t11[2])), t11[3]), dx),
            dy);

    // Interpolate the PDF
    return mix(mix(t00.x, t10.x, dx), mix(t10.x, t11.x, dx), dy);
}


float EvaluatePDF2(sampler2D sampler, vec2 p, out vec3 L)
{
    ivec2 i;
    vec2 d;
    for(int c = 0; c < 2; ++c)
    {
        if(p[c] <= 0.) { i[c] = 0; d[c] = 0.; }
        else if(p[c] >= 1.) { i[c] = kPDF2Dims[c] - 2; d[c] = 1.; }
        else 
        { 
            p[c] *= float(kPDF2Dims[c] - 1); 
            i[c] = int(p[c]); 
            d[c] = fract(p[c]);
        }
    }


    vec4 t00 = texelFetch(sampler, ivec2(i.x, i.y), 0);
    vec4 t10 = texelFetch(sampler, ivec2(i.x + 1, i.y), 0);
    vec4 t01 = texelFetch(sampler, ivec2(i.x, i.y + 1), 0);
    vec4 t11 = texelFetch(sampler, ivec2(i.x + 1, i.y + 1), 0);

    L = mix(mix(vec3(_unpackHalf2x16(floatBitsToUint(t00[2])), t00[3]), vec3(_unpackHalf2x16(floatBitsToUint(t10[2])), t10[3]), d.x), 
            mix(vec3(_unpackHalf2x16(floatBitsToUint(t01[2])), t01[3]), vec3(_unpackHalf2x16(floatBitsToUint(t11[2])), t11[3]), d.x),
            d.y);            

    return mix(mix(t00.x, t10.x, d.x), mix(t10.x, t11.x, d.x), d.y);
}

// LENS BLOOM PASS

void mainImage( out vec4 rgba, in vec2 xyScreen )
{   
    rgba = vec4(0.0);

    vec3 L0 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.05), vec3(1.5, 1.8, 2.4), iChannel0); 
    vec3 L1 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.1), vec3(1.0, 1.8, 2.4), iChannel0); 

    rgba.x = uintBitsToFloat(_packHalf2x16(L0.xy));
    rgba.y = L0.z;
    rgba.z = uintBitsToFloat(_packHalf2x16(L1.xy));
    rgba.w = L1.z;
}

// ENVIRONMENT SAMPLER PMF CONSTRUCTION

void mainImage( out vec4 rgba, in vec2 xyScreen )
{    
    rgba = vec4(kZero, 1.0);

    // x: normalised PMF
    // y: normalised CMF  
    // zw: half-precision RGB environment value

    if(int(xyScreen.x) >= kPDF2Width + 1 || int(xyScreen.y) >= kPDF2Height) { return; }

    int x = int(xyScreen.x);
    int y = int(xyScreen.y);

    rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);

    // Build the CDF iteratively over a few frames. We could simply brute-force integrate it all at once,
    // but this would stall the shader for big CDFs. Accept a small delay to save on compute time.
    if(iFrame == 0)
    {    
        float phi = kTwoPi * xyScreen.x / float(kPDF2Width);
        float theta = kPi * xyScreen.y / float(kPDF2Height);

        // NOTE: We're only sampling the upper hemisphere for this demo
        rgba *= 0.;
        if(phi < kPi)
        {    
            rgba = vec4(cwiseMax(EvaluateCubemap(iChannel1, theta, phi)));
            rgba.w *= sin(theta);
            rgba.y = 0.;        
        }
    }
    else if(iFrame == 1)
    {
        // Integrate the area of each logical cell in the grid
        rgba.y = (x == 0) ? 0. : (0.5 * (texelFetch(iChannel0, ivec2(x, y), 0).x + texelFetch(iChannel0, ivec2(x - 1, y), 0).x));
        rgba.y *= sin(kPi * xyScreen.y / float(kPDF2Height));

    }
    else if(iFrame < 2 + kPDF2PhiSteps)
    {   
        int localFrame = iFrame - 2;

        // Iterative reduce. Needs O(log n) texture taps instead O(n)
        int subIdx = x >> localFrame;        
        if((subIdx & 1) == 1)
        {
            uint subCDFPrev = (uint(x) & ~((1u << localFrame) - 1u)) - 1u;
            if(subCDFPrev != 0xffffffffu)
            {
                rgba.yw += texelFetch(iChannel0, ivec2(subCDFPrev, y), 0).yw;   
            }
        }       
    }
    else if(iFrame == 2 + kPDF2PhiSteps)
    {
        if(x == kPDF2Width)
        {
            // Integrate the area of each logical cell in the grid
            rgba.y = (y == 0) ? 0. : (0.5 * (texelFetch(iChannel0, ivec2(x - 1, y), 0).y + texelFetch(iChannel0, ivec2(x - 1, y - 1), 0).y));
            rgba.xw = texelFetch(iChannel0, ivec2(x - 1, y), 0).yw;
        }
    }
    else if(iFrame < 3 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        int localFrame = iFrame - (3 + kPDF2PhiSteps);

        if(x == kPDF2Width)
        {                        
            int subIdx = y >> localFrame;        
            if((subIdx & 1) == 1)
            {
                uint subCDFPrev = (uint(xyScreen.y) & ~((1u << localFrame) - 1u)) - 1u;
                if(subCDFPrev != 0xffffffffu)
                {
                    rgba.yw += texelFetch(iChannel0, ivec2(kPDF2Width, subCDFPrev), 0).yw;          
                }
            }       
        }
    }
      // Normalise the theta PDF
    else if(iFrame == 3 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        if(int(xyScreen.x) == kPDF2Width)
        {
            float norm = max(1e-10, texelFetch(iChannel0, ivec2(kPDF2Width, kPDF2Height - 1), 0).y);
            rgba.x /= norm;
            rgba.y /= norm;
            rgba.z = texelFetch(iChannel0, ivec2(kPDF2Width - 2, y), 0).y;
        }
    }
    // Normalise the phi PDFs
    else if(iFrame == 4 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        if(int(xyScreen.x) < kPDF2Width)
        {
            // Normalise the values
            float rowNorm = max(1e-10, texelFetch(iChannel0, ivec2(kPDF2Width - 1, y), 0).y);
            rgba.y /= rowNorm;
            rgba.x *= float(kPDF2Width * kPDF2Height) / max(1e-10, texelFetch(iChannel0, ivec2(kPDF2Width, kPDF2Height - 1), 0).w);
            rgba.x *= 2. / kPi;

            // Re-evaluate the environment and encode it 
            float phi = kTwoPi * xyScreen.x / float(kPDF2Width);
            float theta = kPi * xyScreen.y / float(kPDF2Height);                           

            vec3 rgb =EvaluateCubemap(iChannel1, theta, phi);
            rgba.z = uintBitsToFloat(_packHalf2x16(rgb.xy));
            rgba.w = rgb.z;
        }
    }
}
